pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {GameItems} from "../src/GameItems.sol";

contract GameItemsHarness is GameItems {
    constructor(address ownerAddress, address treasuryAddress_)
        GameItems(ownerAddress, treasuryAddress_)
    {}

    function mintFor(address to, uint256 id, uint256 amount) external {
        _mint(to, id, amount, "");
    }
}

contract InvMutTest is Test {
    GameItemsHarness items;
    uint256 constant LOCKED = 0;
    uint256 constant OPEN = 1;

    function onERC1155Received(address, address, uint256, uint256, bytes calldata)
        external
        pure
        returns (bytes4)
    {
        return 0xf23a6e61;
    }

    function onERC1155BatchReceived(address, address, uint256[] calldata, uint256[] calldata, bytes calldata)
        external
        pure
        returns (bytes4)
    {
        return 0xbc197c81;
    }

    function setUp() public {
        items = new GameItemsHarness(address(this), address(this));
        items.createGameItem("locked", "uriL", false, false, 0, 0, 1);
        items.createGameItem("open", "uriO", false, true, 0, 0, 1);
    }

    function _batchReverts(address from, address to, uint256 id, uint256 amount)
        internal
        returns (bool)
    {
        uint256[] memory ids = new uint256[](1);
        ids[0] = id;
        uint256[] memory amts = new uint256[](1);
        amts[0] = amount;
        try items.safeBatchTransferFrom(from, to, ids, amts, "") {
            return false;
        } catch {
            return true;
        }
    }

    function testFuzz_lockedItemNotBatchTransferable(address to, uint96 amount) public {
        vm.assume(to != address(0));
        vm.assume(uint160(to) > 9);
        vm.assume(to.code.length == 0);
        uint256 amt = uint256(amount) + 1;

        items.mintFor(address(this), LOCKED, amt);
        assertEq(items.balanceOf(address(this), LOCKED), amt);

        assertTrue(
            _batchReverts(address(this), to, LOCKED, amt),
            "locked item was batch-transferable"
        );
        assertEq(items.balanceOf(address(this), LOCKED), amt);
        assertEq(items.balanceOf(to, LOCKED), 0);
    }
}
